import http from "node:http";const port=Number(process.env.PORT||8080);const chains=(process.env.MDI_CHAIN_NETWORKS||"").split(",").map(x=>x.trim()).filter(Boolean);if(!chains.length)console.warn(JSON.stringify({component:"mdi-chain-indexer",event:"provider_gated"}));const s=http.createServer((req,res)=>{res.writeHead(req.url==="/health"?200:404,{"content-type":"application/json"});res.end(JSON.stringify(req.url==="/health"?{status:"ok",service:"mdi-chain-indexer",networks:chains}:{error:"not_found"}));});s.listen(port,"0.0.0.0");